-- Tables exported from UAVSurveys_archive.db on 2026-11-05
PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

-- LabelClasses: 1 rows
DROP TABLE IF EXISTS "LabelClasses";
CREATE TABLE LabelClasses (LabelClassName TEXT (10) PRIMARY KEY UNIQUE, LabelClassDesc TEXT (30));

-- LabelsClassSets: 1 rows
DROP TABLE IF EXISTS "LabelsClassSets";
CREATE TABLE LabelsClassSets (LabelClassSetId INTEGER PRIMARY KEY AUTOINCREMENT, LabelClassId TEXT (10) REFERENCES LabelClasses (LabelClassName) ON UPDATE CASCADE);

-- Models: 1 rows
DROP TABLE IF EXISTS "Models";
CREATE TABLE Models (ModelName TEXT (15) PRIMARY KEY UNIQUE, ModelDateCreated TEXT (10), ModelAlgorthim TEXT (15), LabelClassSetId TEXT (10) REFERENCES LabelsClassSets (LabelClassSetId) ON UPDATE CASCADE, ModelTrainData TEXT (255));

-- Locations: 3 rows
DROP TABLE IF EXISTS "Locations";
CREATE TABLE Locations (Location TEXT (20) PRIMARY KEY UNIQUE, LocationId TEXT (4) UNIQUE, Latitude NUMERIC (19, 6), Longitude NUMERIC (19, 6));

-- UAVs: 5 rows
DROP TABLE IF EXISTS "UAVs";
CREATE TABLE UAVs (ModelName TEXT (10) PRIMARY KEY UNIQUE, Manufacturer TEXT (10));

-- ManualCountsOccupied: 19 rows
DROP TABLE IF EXISTS "ManualCountsOccupied";
CREATE TABLE ManualCountsOccupied (Year TEXT (4), SurveyId TEXT (20) REFERENCES Surveys (SurveyId) ON UPDATE CASCADE, Colony TEXT (4), SurveyDate TEXT (10), FirstOccupiedCt INTEGER, FirstInitials TEXT, StandingOccupiedCt INTEGER, ReviewOccupiedCt INTEGER, ReviewInitials TEXT, FinalOccupiedCt INTEGER, CountedOrtho TEXT, OrthomosaicName TEXT (20) REFERENCES SurveyImagery (OrthomosaicName) ON UPDATE CASCADE);

-- HumanLabels: 36 rows
DROP TABLE IF EXISTS "HumanLabels";
CREATE TABLE HumanLabels (SurveyId TEXT (20) REFERENCES Surveys (SurveyId) ON UPDATE CASCADE, LabelsClassSetId INTEGER (4) REFERENCES LabelsClassSets (LabelClassSetId) ON UPDATE CASCADE, ValidationTilesNum INTEGER (5), ValidationLabelsNum INTEGER (5), ValidInitials, TrainingTilesNum INTEGER (5), TrainingLabelsNum INTEGER (5), TrainingLabelsLoc TEXT (30), TestTilesNum INTEGER (5), TestLabelsNum INTEGER (5), TestLabelsLoc TEXT (30));

-- Surveys: 45 rows
DROP TABLE IF EXISTS "Surveys";
CREATE TABLE Surveys (SurveyId TEXT (20) PRIMARY KEY UNIQUE, LocationId TEXT (4) REFERENCES Locations (LocationId) ON UPDATE CASCADE, SurveyStartDate TEXT (10), SurveyStartTime TEXT (5), SurveyEndDate TEXT (10), SurveyEndTime TEXT (5), FlightMode TEXT (10), LandingMode TEXT (10), SurveyAltitude INTEGER (3), SurveySpeed INTEGER (2), UAVModel TEXT (10) REFERENCES UAVs (ModelName) ON UPDATE CASCADE, NumUAVs INTEGER (1), Camera TEXT (15), ISO NUMERIC (4), ShutterSpeed NUMERIC (4), Aperture NUMERIC (3, 1), ImgFormat TEXT (7), GridSpace INTEGER (3), EstOverlapX NUMERIC (3, 1), EstOverlapY, GSD NUMERIC, Pilots TEXT (30), Weather TEXT (30));

-- ModelPredictions: 30 rows
DROP TABLE IF EXISTS "ModelPredictions";
CREATE TABLE ModelPredictions (PredictId INTEGER PRIMARY KEY NOT NULL, SurveyId TEXT (20) REFERENCES Surveys (SurveyId) ON UPDATE CASCADE, OrthomosaicName TEXT REFERENCES SurveyImagery (OrthomosaicName) ON UPDATE CASCADE, SeasonYr INTEGER (4), ModelName TEXT (20) REFERENCES Models (ModelName), Precision NUMERIC (3, 2), Recall NUMERIC (3, 2), F1Score NUMERIC (3, 2), Threshold NUMERIC (4, 2), TCR NUMERIC, MaskedCleaned INTEGER, InitialConfThreshold NUMERIC (4, 3), UNIQUE (OrthomosaicName, ModelName, Threshold));

-- SurveyImagery: 43 rows
DROP TABLE IF EXISTS "SurveyImagery";
CREATE TABLE SurveyImagery (OrthomosaicName TEXT (20) PRIMARY KEY UNIQUE, SurveyId TEXT (20) REFERENCES Surveys (SurveyId) ON UPDATE CASCADE, ImagesLoc TEXT, Stitched TEXT (1), StitchQuality TEXT (6), InDejuPenguinSci TEXT, Tiled TEXT (1), TilesLoc TEXT (30), TileXDimension INTEGER (4), TileYDimension INTEGER (4), GeoRefTableName TEXT (30), OrthoProjection TEXT (30), OrthoXResolution NUMERIC (3, 9), OrthoYResolution NUMERIC (3, 9));

-- GroundCounts: 426 rows
DROP TABLE IF EXISTS "GroundCounts";
CREATE TABLE GroundCounts (col TEXT, season_yr NUMERIC, date TEXT, subcol TEXT, active_ct REAL, occ_ct REAL, total_ct REAL);

-- CalibratedCounts: 30 rows
DROP TABLE IF EXISTS "CalibratedCounts";
CREATE TABLE CalibratedCounts (PredictId NUMERIC PRIMARY KEY, SurveyId TEXT REFERENCES Surveys (SurveyId) ON UPDATE CASCADE, OrthomosaicName TEXT REFERENCES SurveyImagery (OrthomosaicName) ON UPDATE CASCADE, CandidateNestTotal INTEGER, NCells INTEGER, Observer1 TEXT, Observer2 TEXT, R_CN_Obs1 REAL, R_CN_Obs2 REAL, ObsPctDiff_CN REAL, ObsDiff_CN INTEGER, R_ManualCN_ModelCN REAL, AdjCNTotal INTEGER, AdjCNMoE INTEGER, AdjCNCIPct REAL, CNBiasSig INTEGER, R_Occ_Obs1 REAL, R_Occ_Obs2 REAL, ObsDiff_Occ INTEGER, ObsPctDiff_Occ REAL, R_Occ_ManCN REAL, EstOccTotal INTEGER, OccMoE INTEGER, OccCIPct REAL, R_TI_Obs1 REAL, R_TI_Obs2 REAL, ObsDiff_TI INTEGER, ObsPctDiff_TI REAL, R_TI_ManCN REAL, EstTITotal INTEGER, TIMoE INTEGER, TICIPct REAL, Obs1Time REAL, Obs2Time REAL, ActiveFromOcc INTEGER, ActiveFromTotal INTEGER, ActiveFromOccMoE INTEGER, ActiveFromTotalMoE INTEGER, R_Act_Occ REAL, R_Act_TI REAL, R_Act_Occ_SE REAL, R_Act_TI_SE REAL, ActiveFromOccCIPct REAL, ActiveFromTotalCIPct REAL, R_AdjCN_ActOcc REAL, R_AdjCN_ActTI REAL);

COMMIT;
