INSERT INTO "Surveys" ("SurveyId", "LocationId", "SurveyStartDate", "SurveyStartTime", "SurveyEndDate", "SurveyEndTime", "FlightMode", "LandingMode", "SurveyAltitude", "SurveySpeed", "UAVModel", "NumUAVs", "Camera", "ISO", "ShutterSpeed", "Aperture", "ImgFormat", "GridSpace", "EstOverlapX", "EstOverlapY", "GSD", "Pilots", "Weather") VALUES ('croz_adpe_2025-01-12', 'CROZ', '2025-01-12', '13:23', '2025-12-13', '15:45', 'Autonomous', 'RTH', 40, 5, 'Mavic 3E', 2, 'Mavic3E', 800, 1000, 8, 'JPG', NULL, NULL, NULL, NULL, 'Grant Ballard, Christina Burnham', 'Overcast on the first day and windy: gusting to 22 kts over the ridge in QR routes. Wind to 4.5 kts at CM snow LZ. Second day at E. Rook was mostly sunny with mild breeze.');
