INSERT INTO "Surveys" ("SurveyId", "LocationId", "SurveyStartDate", "SurveyStartTime", "SurveyEndDate", "SurveyEndTime", "FlightMode", "LandingMode", "SurveyAltitude", "SurveySpeed", "UAVModel", "NumUAVs", "Camera", "ISO", "ShutterSpeed", "Aperture", "ImgFormat", "GridSpace", "EstOverlapX", "EstOverlapY", "GSD", "Pilots", "Weather") VALUES ('royd_adpe_2025-12-02', 'ROYD', '2025-12-02', '11:37', '2025-12-02', '11:45', 'Autonomous', 'RTH', 40, 5, 'Mavic 3E', 1, 'Mavic3E', 400, 1000, 8, 'JPG', NULL, NULL, NULL, 1.09, 'Dennis Jongsomjit', 'Mostly sunny, wind avg of 5.6 kts at camp LZ.');
INSERT INTO "Surveys" ("SurveyId", "LocationId", "SurveyStartDate", "SurveyStartTime", "SurveyEndDate", "SurveyEndTime", "FlightMode", "LandingMode", "SurveyAltitude", "SurveySpeed", "UAVModel", "NumUAVs", "Camera", "ISO", "ShutterSpeed", "Aperture", "ImgFormat", "GridSpace", "EstOverlapX", "EstOverlapY", "GSD", "Pilots", "Weather") VALUES ('royd_adpe_2026-01-12', 'ROYD', '2026-01-12', '14:40', '2026-01-12', '14:56', 'Autonomous', 'Manual', 40, 5, 'ANAFI', 1, 'Parrot ANAFI', 100, 1000, 2.4, 'JPG', NULL, NULL, NULL, NULL, 'Christina Burnham', 'Overcast, gusting to 8 kts over the ridge and sustained 3 kts at the LZ. -5 deg C.');
INSERT INTO "Surveys" ("SurveyId", "LocationId", "SurveyStartDate", "SurveyStartTime", "SurveyEndDate", "SurveyEndTime", "FlightMode", "LandingMode", "SurveyAltitude", "SurveySpeed", "UAVModel", "NumUAVs", "Camera", "ISO", "ShutterSpeed", "Aperture", "ImgFormat", "GridSpace", "EstOverlapX", "EstOverlapY", "GSD", "Pilots", "Weather") VALUES ('royd_adpe_2025-11-19', 'ROYD', '2025-11-19', '12:52', '2025-11-19', '13:00', 'Autonomous', 'RTH', 40, 5, 'Mavic 3E', 1, 'Mavic3E', 200, 1000, 8, 'JPG', NULL, NULL, NULL, NULL, 'Christina Burnham', 'Mostly sunny. Slightly windy, with wind blowing to 13 mph at LZ, but remained under 15 kts and no high wind warning.');
INSERT INTO "Surveys" ("SurveyId", "LocationId", "SurveyStartDate", "SurveyStartTime", "SurveyEndDate", "SurveyEndTime", "FlightMode", "LandingMode", "SurveyAltitude", "SurveySpeed", "UAVModel", "NumUAVs", "Camera", "ISO", "ShutterSpeed", "Aperture", "ImgFormat", "GridSpace", "EstOverlapX", "EstOverlapY", "GSD", "Pilots", "Weather") VALUES ('croz_empe_2025-11-22', 'CROZ', '2025-11-22', '11:06', '2025-11-22', '11:58', 'Autonomous', 'RTH', 50, 5, 'Mavic 3E', 1, 'Mavic3E', 200, 1000, 9, 'JPG', NULL, NULL, NULL, NULL, 'Christina Burnham, Dennis Jongsomjit', 'Mostly sunny. Whispy clouds above. Windspeed avg 7.3 kts at LZ, gusting to 9 kts. Wind speed over shelf 5-6 m/s.');
INSERT INTO "Surveys" ("SurveyId", "LocationId", "SurveyStartDate", "SurveyStartTime", "SurveyEndDate", "SurveyEndTime", "FlightMode", "LandingMode", "SurveyAltitude", "SurveySpeed", "UAVModel", "NumUAVs", "Camera", "ISO", "ShutterSpeed", "Aperture", "ImgFormat", "GridSpace", "EstOverlapX", "EstOverlapY", "GSD", "Pilots", "Weather") VALUES ('croz_adpe_2025-11-26', 'CROZ', '2025-11-26', '11:19', '2025-11-26', '16:17', 'Autonomous', 'RTH', 40, 5, 'Mavic 3E', 2, 'Mavic3E', 400, 1000, 9, 'JPG', NULL, NULL, NULL, 1.08, 'Christina Burnham, Dennis Jongsomjit', 'At the beginning of the survey, it was mostly sunny with scattered clouds that cast sections of the colony into darkness. At CM snow LZ, it was gusting to 8 kts. At B LZ, it was gusting to 3.5 kts. At QR LZ, the wind averaged 5.1 kts and gusted to 12.3 kts. At E. Rook, which was flown later in the afternoon, it had become overcast with light snow.');
INSERT INTO "Surveys" ("SurveyId", "LocationId", "SurveyStartDate", "SurveyStartTime", "SurveyEndDate", "SurveyEndTime", "FlightMode", "LandingMode", "SurveyAltitude", "SurveySpeed", "UAVModel", "NumUAVs", "Camera", "ISO", "ShutterSpeed", "Aperture", "ImgFormat", "GridSpace", "EstOverlapX", "EstOverlapY", "GSD", "Pilots", "Weather") VALUES ('bird_adpe_2025-12-01', 'BIRD', '2025-12-01', '12:10', '2025-12-01', '15:45', 'Autonomous', 'RTH', 40, 5, 'Mavic 3E', 2, 'Mavic3E', 800, 1000, 8, 'JPG', NULL, NULL, NULL, 1.03, 'Christina Burnham, Dennis Jongsomjit', 'Mostly sunny but with a marine layer over water and drifting over colony. Wind to 6.5 kts at N.Bird LZ, 7.2 kts at Middle LZ, and 14.1 kts at S.Bird LZ.');
INSERT INTO "Surveys" ("SurveyId", "LocationId", "SurveyStartDate", "SurveyStartTime", "SurveyEndDate", "SurveyEndTime", "FlightMode", "LandingMode", "SurveyAltitude", "SurveySpeed", "UAVModel", "NumUAVs", "Camera", "ISO", "ShutterSpeed", "Aperture", "ImgFormat", "GridSpace", "EstOverlapX", "EstOverlapY", "GSD", "Pilots", "Weather") VALUES ('croz_adpe_2026-01-12', 'CROZ', '2026-01-12', '13:20', '2026-01-12', '18:04', 'Autonomous', 'Manual', 40, 5, 'ANAFI', 2, 'Parrot ANAFI', 200, 1000, 2.4, 'JPG', NULL, NULL, NULL, NULL, 'Annie Schmidt, Grant Ballard', 'Cold, cloudy, a bit breezy. 9.2 mph (8 kts) at QR LZ and 7-9 mph (6-8 kts) at B LZ at ~ 1300. At erook at 17:35, winde 5.6 mph');
INSERT INTO "Surveys" ("SurveyId", "LocationId", "SurveyStartDate", "SurveyStartTime", "SurveyEndDate", "SurveyEndTime", "FlightMode", "LandingMode", "SurveyAltitude", "SurveySpeed", "UAVModel", "NumUAVs", "Camera", "ISO", "ShutterSpeed", "Aperture", "ImgFormat", "GridSpace", "EstOverlapX", "EstOverlapY", "GSD", "Pilots", "Weather") VALUES ('croz_spsk_2025-12-26', 'CROZ', '2025-12-26', '16:00', '2025-12-26', '17:40', 'Autonomous', 'RTH', 25, 4, 'ANAFI', 2, 'Parrot ANAFI', 200, 2000, 2.4, 'JPG', NULL, NULL, NULL, NULL, 'Annie Schmidt, Grant Ballard', 'Sunny and clear, with mild wind from ENE.');
